import React, { useMemo } from 'react';
import {
  Box,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Grid,
  Stack,
  TextField,
  Typography,
  useMediaQuery,
} from '@mui/material';
import Inventory2OutlinedIcon from '@mui/icons-material/Inventory2Outlined';
import { useFormik } from 'formik';
import { useAdjustStockMutation } from '../../page/posApi';
import { theme } from '../../theme';
import { useTranslation } from 'react-i18next';
import FieldHeader from '../../components/FieldHeader';
import { useNotifier } from '../../core/Notifier';
import { HEADER_GRADIENT } from '../../theme/appColors';

export interface IStockAdjust {
  productId: string;
  currentStock: number;
  remark: string;
}

interface IStockAdjustPopupProps {
  open: boolean;
  title: string;
  handleClose: () => void;
  productId: string;
  stockAvailable: number;
  onUpdate: (currentStock: number) => void;
}

const StockAdjustPopup: React.FC<IStockAdjustPopupProps> = ({
  open,
  title,
  handleClose,
  productId,
  stockAvailable,
  onUpdate,
}) => {
  const { t } = useTranslation(['common']);
  const [adjustStock, { isLoading }] = useAdjustStockMutation();
  const { showErrorMessage, showMessage } = useNotifier();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));

  const formik = useFormik<IStockAdjust>({
    initialValues: { productId, currentStock: 0, remark: '' },
    onSubmit: async (values) => {
      try {
        const response = await adjustStock(values).unwrap();
        if (response.status) {
          showMessage(response.message);
          onUpdate(values.currentStock);
          handleClose();
        } else {
          showErrorMessage(response.message);
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
    validate: () => ({}),
  });

  const formValid = useMemo(
    () => formik.values.currentStock >= 0 && formik.values.remark !== '' && formik.values.remark !== undefined,
    [formik.values]
  );

  const inputSx = {
    '& .MuiOutlinedInput-root': {
      borderRadius: '8px',
      '&.Mui-focused fieldset': { borderColor: '#0F8B8D' },
    },
    '& label.Mui-focused': { color: '#0F8B8D' },
  };

  return (
    <Dialog
      aria-describedby="alert-dialog-description"
      fullScreen={isMobile}
      fullWidth
      maxWidth="xs"
      open={open}
      PaperProps={{
        sx: { borderRadius: isMobile ? 0 : '12px', overflow: 'hidden' },
      }}
    >
      <DialogTitle sx={{ p: 0 }}>
        <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
          <Stack alignItems="center" direction="row" spacing={1.5}>
            <Box
              sx={{
                alignItems: 'center',
                background: 'rgba(255,255,255,0.15)',
                borderRadius: '8px',
                display: 'flex',
                height: 36,
                justifyContent: 'center',
                width: 36,
                flexShrink: 0,
              }}
            >
              <Inventory2OutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>
                {title}
              </Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>
                Adjust product inventory
              </Typography>
            </Box>
          </Stack>
        </Box>
      </DialogTitle>

      <DialogContent sx={{ px: 3, pt: 3, pb: 1 }}>
        {/* Current stock badge */}
        <Box
          sx={{
            alignItems: 'center',
            background: 'rgba(15,139,141,0.07)',
            border: '1px solid rgba(15,139,141,0.2)',
            borderRadius: '8px',
            display: 'flex',
            justifyContent: 'space-between',
            mb: 3,
            px: 2,
            py: 1.5,
          }}
        >
          <Typography sx={{ color: '#475569', fontSize: '0.84rem', fontWeight: 500 }}>
            Available Stock
          </Typography>
          <Typography sx={{ color: '#0F8B8D', fontSize: '1.1rem', fontWeight: 800 }}>
            {stockAvailable}
          </Typography>
        </Box>

        <Grid container spacing={2}>
          <Grid item xs={12}>
            <FieldHeader title="Current Stock" />
            <TextField
              InputProps={{ inputProps: { min: 0 } }}
              autoComplete="off"
              fullWidth
              placeholder="Enter current stock"
              size="small"
              sx={inputSx}
              type="number"
              {...formik.getFieldProps('currentStock')}
            />
          </Grid>
          <Grid item xs={12}>
            <FieldHeader title="Remarks" />
            <TextField
              autoComplete="off"
              fullWidth
              placeholder="Enter remarks"
              size="small"
              sx={inputSx}
              {...formik.getFieldProps('remark')}
            />
          </Grid>
        </Grid>
      </DialogContent>

      <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
        <Button
          onClick={handleClose}
          sx={{
            borderColor: '#CBD5E1',
            borderRadius: '8px',
            color: '#475569',
            fontWeight: 600,
            height: 40,
            minWidth: 100,
            px: 3,
            textTransform: 'none',
            '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' },
          }}
          variant="outlined"
        >
          {t('common:cancel')}
        </Button>
        <Button
          autoFocus
          disabled={!formValid || isLoading}
          onClick={() => formik.handleSubmit()}
          sx={{
            background: HEADER_GRADIENT,
            borderRadius: '8px',
            boxShadow: '0 4px 14px rgba(15,29,77,0.25)',
            color: '#fff',
            fontWeight: 700,
            height: 40,
            minWidth: 100,
            px: 3,
            textTransform: 'none',
            '&:hover': { opacity: 0.9 },
            '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8', boxShadow: 'none' },
          }}
          type="submit"
          variant="contained"
        >
          {isLoading ? <CircularProgress size={18} sx={{ color: '#fff' }} /> : t('common:update')}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default React.memo(StockAdjustPopup);
