import FileDownloadIcon from '@mui/icons-material/FileDownload';
import Inventory2OutlinedIcon from '@mui/icons-material/Inventory2Outlined';
import SearchIcon from '@mui/icons-material/Search';
import {
  Box,
  Button,
  CircularProgress,
  InputAdornment,
  TextField,
  Tooltip,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import { Table } from '@tanstack/react-table';
import { saveAs } from 'file-saver';
import React, { useEffect, useMemo, useState } from 'react';
import * as XLSX from 'xlsx';

import ReactTable from '../../components/Table/ReactTable';
import PosTablePagination from '../../components/Table/PosTablePagination';
import StockAdjustPopup from '../../components/ModelPopup/StockAdjustmentPopup';
import AnimatedPage from '../../layouts/AnimatedPage';
import { appColors, HEADER_GRADIENT } from '../../theme/appColors';
import { IUserInfo } from '../../core/Interface/user.interface';
import { Privileges } from '../../core/types/commonType';
import {
  IInventoryDetailsData,
  IInventoryDetails,
} from '../../core/Interface/inventory.interface';
import useInventoryDetails from './useInventoryDetails';
import usePageQuery from '../../core/hooks/usePageQuery';
import { useGetAllInventoryQuery, useGetUserQuery } from '../posApi';

interface IAllInventoryResponse {
  data: IInventoryDetails;
}

const InventoryDetails: React.FC = () => {
  const [selectedProduct, setSelectedProduct] =
    useState<IInventoryDetailsData | null>(null);
  const [open, setOpen] = useState(false);
  const [, setTableData] = useState<IInventoryDetailsData[]>([]);
  const [localSearch, setLocalSearch] = useState('');

  const handleOpenStockAdjust = (product: IInventoryDetailsData) => {
    setSelectedProduct(product);
    setOpen(true);
  };

  const { table, isLoading, totalCount, setSearchText } = useInventoryDetails(
    handleOpenStockAdjust
  );
  const { setPage } = usePageQuery();

  const { data: companyData } = useGetUserQuery();
  const { data: allInventoryResponse, isFetching: isFetchingAll } =
    useGetAllInventoryQuery({
      pageIndex: 0,
      pageSize: 100000,
      searchText: '',
    });


  const hasDownloadPermission =
    (companyData?.data as IUserInfo)?.privileges?.includes(
      Privileges.Download_Excel_Inventory
    ) ?? false;

  const handleCloseStockAdjust = () => {
    setSelectedProduct(null);
    setOpen(false);
  };

  const handleUpdateStock = (newStock: number) => {
    if (!selectedProduct) return;
    setTableData((prev) =>
      prev.map((row) =>
        row.id === selectedProduct.id
          ? { ...row, stockAvailable: newStock }
          : row
      )
    );
  };

  const handlePaginationChangePage = (
    event: React.MouseEvent<HTMLButtonElement> | null,
    newPage: number
  ) => {
    if (table.getState().pagination.pageIndex < newPage) {
      table.nextPage?.();
    } else {
      table.previousPage?.();
    }
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    table.setPageSize?.(parseInt(event.target.value, 10));
  };

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setLocalSearch(e.target.value);
  };

  const handleDownloadAllInventory = () => {
    if (!allInventoryResponse) return;
    const allInventoryData = (
      allInventoryResponse.data as IAllInventoryResponse['data']
    )?.records;
    if (!allInventoryData?.length) return;

    const formattedData = allInventoryData.map((item) => ({
      Code: item.code,
      'Product Name': item.name,
      'Category Code': item.categoryCode,
      'Category Name': item.categoryName,
      'Stock Available': item.stockAvailable,
      'Unit Price': item.unitPrice,
    }));

    const worksheet = XLSX.utils.json_to_sheet(formattedData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Inventory');
    const excelBuffer = XLSX.write(workbook, {
      bookType: 'xlsx',
      type: 'array',
    });
    saveAs(
      new Blob([excelBuffer], { type: 'application/octet-stream' }),
      'All Inventory.xlsx'
    );
  };

  const rows = useMemo(
    () => table.getRowModel?.()?.rows ?? [],
    [table]
  );

  useEffect(() => {
    if (rows.length > 0) setTableData(rows.map((row) => row.original));
  }, [rows]);

  useEffect(() => {
    if (!isLoading && rows.length === 0) setPage(0);
  }, [isLoading, rows, setPage]);

  return (
    <AnimatedPage>
      <Box
        data-testid="InventoryDetails"
        sx={{
          display: 'flex',
          flexDirection: 'column',
          height: 'calc(100vh - 112px)',
          overflow: 'hidden',
        }}
      >
        {/* Hero banner */}
        <Box
          sx={{
            background: HEADER_GRADIENT,
            borderRadius: 2,
            color: '#fff',
            flexShrink: 0,
            mb: 2,
            overflow: 'hidden',
            position: 'relative',
            px: { xs: 2, md: 3 },
            py: { xs: 1.5, md: 2 },
          }}
        >
          <Box
            sx={{
              background: 'rgba(255,255,255,0.07)',
              borderRadius: '50%',
              height: 220,
              inset: 'auto -60px -100px auto',
              pointerEvents: 'none',
              position: 'absolute',
              width: 220,
            }}
          />
          <Box
            sx={{
              background: 'rgba(255,255,255,0.05)',
              borderRadius: '50%',
              height: 260,
              inset: '-100px auto auto 55%',
              pointerEvents: 'none',
              position: 'absolute',
              width: 260,
            }}
          />

          <Box
            sx={{
              alignItems: { xs: 'flex-start', sm: 'center' },
              display: 'flex',
              flexDirection: { xs: 'column', sm: 'row' },
              gap: 2,
              justifyContent: 'space-between',
              position: 'relative',
            }}
          >
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
              <Box
                sx={{
                  alignItems: 'center',
                  backdropFilter: 'blur(8px)',
                  background: 'rgba(255,255,255,0.14)',
                  border: '1px solid rgba(255,255,255,0.18)',
                  borderRadius: '10px',
                  display: 'flex',
                  height: 44,
                  justifyContent: 'center',
                  width: 44,
                }}
              >
                <Inventory2OutlinedIcon
                  sx={{ color: '#fff', fontSize: 22 }}
                />
              </Box>
              <Box>
                <Typography
                  sx={{
                    color: '#fff',
                    fontSize: { xs: '1rem', md: '1.2rem' },
                    fontWeight: 800,
                    letterSpacing: '-0.02em',
                    lineHeight: 1.2,
                  }}
                >
                  Inventory Details
                </Typography>
                <Typography
                  sx={{
                    color: 'rgba(255,255,255,0.72)',
                    fontSize: '0.78rem',
                  }}
                >
                  {isLoading
                    ? '—'
                    : `${totalCount} record${totalCount !== 1 ? 's' : ''}`}
                </Typography>
              </Box>
            </Box>

            {hasDownloadPermission && (
              <Tooltip title="Download all inventory as Excel">
                <span>
                  <Button
                    disabled={isFetchingAll}
                    onClick={handleDownloadAllInventory}
                    startIcon={
                      isFetchingAll ? (
                        <CircularProgress
                          size={14}
                          sx={{ color: '#fff' }}
                        />
                      ) : (
                        <FileDownloadIcon />
                      )
                    }
                    sx={{
                      background:
                        'linear-gradient(135deg, #059669 0%, #047857 100%)',
                      borderRadius: '8px',
                      boxShadow: `0 4px 14px ${alpha('#059669', 0.45)}`,
                      color: '#fff',
                      flexShrink: 0,
                      fontWeight: 700,
                      height: 40,
                      px: 2.5,
                      '&:hover': {
                        background:
                          'linear-gradient(135deg, #047857 0%, #065f46 100%)',
                      },
                      '&.Mui-disabled': {
                        background: alpha('#059669', 0.35),
                        color: alpha('#fff', 0.7),
                      },
                    }}
                    variant="contained"
                  >
                    <Box component="span" sx={{ display: { xs: 'none', md: 'inline' } }}>
                      Download
                    </Box>
                  </Button>
                </span>
              </Tooltip>
            )}
          </Box>
        </Box>

        {/* Search */}
        <Box sx={{ alignItems: 'center', display: 'flex', flexShrink: 0, flexWrap: 'wrap', gap: 1.5, mb: 1.5 }}>
          <TextField
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon
                    sx={{ color: alpha('#142352', 0.4), fontSize: 18 }}
                  />
                </InputAdornment>
              ),
            }}
            autoComplete="off"
            onChange={handleSearchChange}
            onKeyDown={(e) => { if (e.key === 'Enter') setSearchText(localSearch); }}
            placeholder="Search by code or product name…"
            size="small"
            sx={{
              flex: { xs: 1, sm: 1, md: 'none' },
              width: { xs: '100%', sm: '100%', md: 340 },
              '& .MuiOutlinedInput-root': {
                backgroundColor: '#fff',
                borderRadius: '8px',
                '& fieldset': {
                  borderColor: alpha(appColors.blueGreyishLight[80], 0.18),
                },
                '&:hover fieldset': {
                  borderColor: alpha('#2563EB', 0.3),
                },
                '&.Mui-focused fieldset': { borderColor: '#2563EB' },
              },
            }}
            value={localSearch}
          />
          <Button
            onClick={() => setSearchText(localSearch)}
            sx={{ borderRadius: '8px', flexShrink: 0, fontWeight: 600, height: 40, px: 2.5 }}
            variant="contained"
          >
            Search
          </Button>
        </Box>

        {/* Table + Pagination — fills remaining height */}
        <Box
          sx={{
            background: '#fff',
            border: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.14)}`,
            borderRadius: '8px',
            display: 'flex',
            flex: 1,
            flexDirection: 'column',
            minHeight: 0,
            overflow: 'hidden',
          }}
        >
          <Box sx={{ flex: 1, minHeight: 0, overflow: 'auto' }}>
            <ReactTable
              isLoading={isLoading}
              {...(table as Table<object>)}
            />
          </Box>

          {table.getTotalSize?.() > 0 && (
            <Box
              sx={{
                borderTop: `1px solid ${alpha(
                  appColors.blueGreyishLight[80], 0.14
                )}`,
                flexShrink: 0,
              }}
            >
              <PosTablePagination
                count={totalCount}
                onPageChange={handlePaginationChangePage}
                onRowsPerPageChange={handleChangeRowsPerPage}
                page={table.getState().pagination.pageIndex ?? 0}
                rowsPerPage={table.getState().pagination.pageSize ?? 10}
                rowsPerPageOptions={[5, 10, 20, 50]}
              />
            </Box>
          )}
        </Box>

        {selectedProduct && (
          <StockAdjustPopup
            handleClose={handleCloseStockAdjust}
            onUpdate={handleUpdateStock}
            open={open}
            productId={selectedProduct.id}
            stockAvailable={selectedProduct.stockAvailable}
            title="Update Stock Count"
          />
        )}
      </Box>
    </AnimatedPage>
  );
};

export default InventoryDetails;
